fix:
Invert conditions to exit or return early using guard clauses, restoring a linear reading path:
```rust
fn process(conn: &mut Connection) -> Result<()> {
    if !conn.is_active() || !conn.has_data() {
        return Ok(());
    }
    let data = conn.read_data();
    if data.is_valid() {
        save(data)?;
    }
    Ok(())
}
```
